"""Eight original CLL questions appended to the lymphoid chapter."""
from create_all import rows,q,AL
from qbank_authoring import ref
CL=ref('iwCLL: Diagnosis, Treatment Indications and Supportive Care','https://ashpublications.org/blood/article/131/25/2745/37141/iwCLL-guidelines-for-diagnosis-indications-for')
EH=ref('EHA: CLL and Richter Transformation Guidelines, 2026','https://pmc.ncbi.nlm.nih.gov/articles/PMC13254007/')
NC=ref('NCI: CLL Treatment—Health Professional PDQ','https://www.cancer.gov/types/leukemia/hp/cll-treatment-pdq')
q('An adult has a persistent clonal B-cell count of 8 × 10^9/L for four months, with small mature lymphocytes coexpressing CD5 and CD23 and a compatible phenotype. Which diagnosis is most likely?', 'Chronic lymphocytic leukemia',[
 ('Monoclonal B-cell lymphocytosis','The count exceeds the usual 5 × 10^9/L threshold for the described uncomplicated distinction.'),('T-ALL','The cells are mature B lymphocytes, not precursor T cells.'),('Hairy cell leukemia','That has a different characteristic phenotype and clinical pattern.')],
 'Use the clonal B-cell count rather than total lymphocytes alone', '**The conventional CLL threshold is at least 5 × 10^9/L clonal B cells sustained for at least three months.**',['Confirm the phenotype by flow cytometry.','Morphological smudge cells are supportive but not independently diagnostic.'], '**Assess clinical stage and treatment need separately.**',['A diagnostic label does not automatically require therapy.','Consider nodal, splenic, immune and marrow manifestations.'],[['Count','Clonal B cells, not total lymphocytes'],['Duration','At least 3 months'],['Phenotype','Compatible mature B-cell pattern']],[CL],style='clinical_scenario')
q('A patient has 2 × 10^9/L circulating CLL-phenotype clonal B cells, no lymphadenopathy or organomegaly and no disease-related cytopenia or symptoms. Which category best fits?', 'Monoclonal B-cell lymphocytosis',[
 ('CLL solely because any clone is detectable','The count and clinical context matter.'),('SLL established without tissue or nodal disease','That is not supported by the stated distribution.'),('Acute leukemia because the clone is B lineage','The cells have a mature phenotype and no acute-leukemia features are given.')],
 'A small mature B-cell clone does not always represent clinical leukemia', '**MBL applies below the CLL count threshold when the relevant disease manifestations are absent.**',['Clone size influences progression risk.','A tissue-based lymphomatous presentation is a different situation.'], '**Use appropriate follow-up rather than automatic treatment.**',['Review new nodes, symptoms or count changes.','Explain the distinction without implying zero future risk.'],[['Count','Below 5 × 10^9/L'],['Clinical findings','No qualifying disease manifestations'],['Category','MBL']],[CL],style='clinical_scenario')
q('An asymptomatic CLL patient has stable lymphocytosis, normal Hb and platelets and no bulky symptomatic disease. What is usual management?', 'Active observation with scheduled reassessment',[
 ('Immediate treatment solely because lymphocytes are above normal','The absolute count alone is not a universal treatment indication.'),('Routine splenectomy despite a normal spleen','There is no described indication.'),('No follow-up because early CLL can never progress','The disease course requires monitoring.')],
 'Treatment is triggered by active disease rather than the label alone', '**Early stable asymptomatic disease is commonly observed.**',['Progressive marrow failure, symptomatic bulky disease or significant disease-related symptoms can change the decision.','The rate of change matters more than a count in isolation.'], '**Monitor symptoms, examination and blood counts.**',['Assess infection and immune complications.','Provide indicated vaccination and supportive-care advice.'],[['Stable asymptomatic','Observation'],['Active disease','Consider treatment'],['Follow-up','Clinical and count trajectory']],[CL,EH],style='clinical_scenario')
q('Which finding is a recognized indication to assess CLL-directed treatment?', 'Progressive disease-related marrow failure causing worsening anemia or thrombocytopenia',[
 ('A single stable elevated lymphocyte count without symptoms','This alone is insufficient.'),('An isolated unconfirmed smudge cell on a smear','That does not establish active disease.'),('A favorable genetic result alone in an otherwise stable patient','Prognostic data alone do not create a treatment indication.')],
 'Active disease can damage marrow function or create substantial burden', '**Progressive cytopenias attributable to CLL can justify treatment.**',['Symptomatic massive nodes or spleen and defined disease-related symptoms are other possibilities.','Exclude alternative causes of the cytopenia.'], '**Do not equate every anemia with marrow replacement.**',['Autoimmune hemolysis, deficiency and renal disease need consideration.','Stable mild abnormalities can have a different urgency from progressive failure.'],[['Indication','Progressive marrow failure'],['Other reasons','Symptomatic or clearly active disease'],['Prerequisite','Correct attribution and assessment']],[CL,EH])
q('A CLL patient now needs treatment and has del(17p) or a pathogenic TP53 mutation. Which principle is most appropriate?', 'Select an effective targeted strategy rather than relying on conventional chemoimmunotherapy as the default',[
 ('The abnormality has no treatment implication','TP53 disruption strongly affects strategy and prognosis.'),('A normal platelet count negates the molecular risk','The genetic effect is not erased by one normal count.'),('All targeted drugs are automatically equivalent for every patient','Comorbidity, prior exposure and evidence still guide choice.')],
 'TP53 status is predictive as well as prognostic', '**TP53 disruption is associated with poor conventional chemoimmunotherapy outcomes.**',['BTK- and BCL2-directed options are important.','Reassess the relevant genetics before a new treatment line.'], '**Choose the exact regimen according to current guidance and patient factors.**',['Cardiovascular risk, renal function and treatment-duration preference matter.','Discuss infection prevention and monitoring.'],[['Biology','TP53 disruption'],['Implication','Targeted-treatment pathway'],['Selection','Current evidence and individual risks']],[EH,NC],style='clinical_scenario')
q('A CLL patient with bulky nodes and reduced renal function is starting venetoclax. Which preventive plan is essential?', 'Tumor-lysis risk assessment with appropriate ramp-up, prophylaxis and laboratory/clinical monitoring',[
 ('Start the full maintenance dose immediately without monitoring','Rapid cell killing can produce dangerous TLS.'),('Assume oral treatment cannot cause TLS','Route does not determine this risk.'),('Use only a baseline Hb to assess metabolic risk','Tumor burden, renal function and metabolic values matter.')],
 'BCL2 inhibition can produce rapid leukemia-cell death', '**Venetoclax initiation follows a structured dose-escalation and TLS-prevention plan.**',['Bulky disease and impaired renal function increase concern.','Hydration, urate control and monitoring intensity are individualized.'], '**Review interacting medicines.**',['CYP3A interactions are particularly important during initiation.','Some patients need inpatient monitoring.'],[['Risk','Tumor burden and renal function'],['Prevention','Ramp-up, hydration and urate strategy'],['Monitoring','Timed laboratory and clinical checks']],[EH,NC],style='clinical_scenario')
q('Which safety history is particularly relevant when selecting a BTK inhibitor for CLL?', 'Atrial arrhythmia, bleeding risk, cardiovascular disease and interacting antithrombotic therapy',[
 ('Only hair color','This is not a meaningful selection factor.'),('No history is needed because all BTK inhibitors have identical safety','Agents differ and patient factors matter.'),('A normal ferritin excludes cardiovascular toxicity','It does not address that risk.')],
 'Efficacy must be paired with a patient-specific toxicity assessment', '**BTK inhibitors can have cardiovascular and bleeding-related adverse effects.**',['Risk varies across agents.','Hypertension, anticoagulation and procedures require planning.'], '**Use current comparative evidence and monitoring.**',['Review drug interactions and adherence.','Select an alternative class when the balance favors it.'],[['Cardiovascular','Arrhythmia and hypertension'],['Hemostasis','Bleeding and antithrombotic exposure'],['Choice','Agent- and patient-specific']],[EH,NC])
q('A previously indolent CLL patient develops a rapidly enlarging asymmetric node, marked LDH rise and new systemic symptoms. What is the priority?', 'Evaluate for Richter transformation with biopsy of an appropriate suspicious site',[
 ('Assume the lymphocyte count alone determines the diagnosis','Transformation can occur without a proportionate blood-count change.'),('Treat as uncomplicated infection without assessing the node','Infection is a differential but the pattern requires tissue evaluation.'),('Diagnose transformation from PET uptake alone','PET can guide the target but tissue is required when feasible.')],
 'A change in tempo can signal a new aggressive histology', '**Richter transformation often represents an aggressive lymphoma arising in CLL.**',['PET can identify a high-yield biopsy site.','Alternative causes include infection and another malignancy.'], '**Obtain adequate tissue for the treatment-changing diagnosis.**',['Do not choose a low-yield site solely for convenience if a more informative safe site exists.','Management differs from routine CLL progression.'],[['Clue','Rapid focal growth and LDH change'],['PET','Biopsy-target selection'],['Confirmation','Tissue histology']],[EH],style='clinical_scenario')
